package com.pp.shaderlod.optimization.blissao;
import net.irisshaders.iris.targets.RenderTargets;import org.lwjgl.opengl.*;import java.util.*;
import com.pp.shaderlod.optimization.makeupao.MakeUpAoGlProof;
import com.pp.shaderlod.optimization.makeupao.MakeUpAoEpoch;
/** Current native depth1/material/normal identity, actual target12 output/return, and current sampler. */
public final class BlissAoGlProof {
 public record Inputs(MakeUpAoGlProof.Binding depth,MakeUpAoGlProof.Binding material,MakeUpAoGlProof.Binding normal,Map<String,Integer> domain){}
 public record Draw(MakeUpAoEpoch.Output output,Inputs inputs,boolean qualified){}
 private BlissAoGlProof(){}
 public static int integer(int p,String name){return MakeUpAoGlProof.integer(p,name);}
 private static MakeUpAoGlProof.Binding binding(int p,String name){return MakeUpAoGlProof.binding(p,name);}
 private static boolean base(MakeUpAoGlProof.Binding b,int w,int h){return b!=null&&b.texture()>0&&b.width()==w&&b.height()==h&&b.base()==0&&b.compare()==GL11.GL_NONE&&b.aniso()==1&&Set.of(GL11.GL_NEAREST,GL11.GL_LINEAR).contains(b.min())&&b.min()==b.mag();}
 private static boolean owned(RenderTargets t,int index,int texture){var rt=t.get(index);return rt!=null&&texture>0&&(texture==rt.getMainTexture()||texture==rt.getAltTexture());}
 private static boolean state(int p,int w,int h,boolean half){int[] v=new int[4];GL11.glGetIntegerv(GL11.GL_VIEWPORT,v);java.nio.ByteBuffer mask=org.lwjgl.BufferUtils.createByteBuffer(4);GL11.glGetBooleanv(GL11.GL_COLOR_WRITEMASK,mask);for(int i=0;i<4;i++)if(mask.get(i)==0)return false;
  int loc=GL20.glGetUniformLocation(p,"gbufferProjection");float[] matrix=new float[16];if(loc<0)return false;GL20.glGetUniformfv(p,loc,matrix);
  return w>=2&&h>=2&&w<=16384&&h<=16384&&BlissAoContract.viewport(v,w,h,half)&&BlissAoContract.projection(matrix)&&integer(p,"shaderlodBridgeVersion")==2&&integer(p,"shaderlodEnabled")==1&&integer(p,"shaderlodOptimizationFlagsVersion")==1&&integer(p,"shaderlodOptAoRenderScale")==1&&Set.of(0,1,2).contains(integer(p,"shaderlodPreset"))&&GL11.glGetInteger(GL20.GL_CURRENT_PROGRAM)==p&&GL20.glGetProgrami(p,GL20.GL_LINK_STATUS)==GL11.GL_TRUE&&GL11.glGetInteger(GL30.GL_DRAW_FRAMEBUFFER_BINDING)>0&&GL30.glCheckFramebufferStatus(GL30.GL_DRAW_FRAMEBUFFER)==GL30.GL_FRAMEBUFFER_COMPLETE&&!GL11.glIsEnabled(GL11.GL_SCISSOR_TEST)&&!GL11.glIsEnabled(GL11.GL_DEPTH_TEST)&&!GL11.glIsEnabled(GL11.GL_STENCIL_TEST)&&!GL11.glIsEnabled(GL11.GL_BLEND)&&!GL11.glIsEnabled(GL30.GL_RASTERIZER_DISCARD);}
 private static Map<String,Integer> domain(int p){var values=new TreeMap<String,Integer>();
  for(String name:List.of("frameCounter","framemod8","shaderlodOptPixelScale","shaderlodBlissPixelQualificationVersion","shaderlodBlissPixelReady","shaderlodBlissPixelProfileQualified","shaderlodBlissPixelSourceQualified","shaderlodBlissPixelLayoutQualified","shaderlodBlissPixelHistoryReady","shaderlodBlissPixelNearQualified","shaderlodBlissPixelClearWeather","shaderlodBlissPixelCurrentEpoch","shaderlodBlissPixelProofEpoch")){int l=GL20.glGetUniformLocation(p,name);if(l>=0)values.put(name,GL20.glGetUniformi(p,l));}
  for(String name:List.of("texelSize","viewWidth","viewHeight","aspectRatio","gbufferProjection","gbufferProjectionInverse","shaderlodBlissPixelCurrentRain")){int l=GL20.glGetUniformLocation(p,name);if(l<0)continue;int count=name.contains("Projection")?16:name.equals("texelSize")?2:1;float[] a=new float[count];GL20.glGetUniformfv(p,l,a);for(int i=0;i<count;i++){if(!Float.isFinite(a[i]))return null;values.put(name+"["+i+"]",Float.floatToRawIntBits(a[i]));}}
  return Map.copyOf(values);
 }
 private static Inputs inputs(RenderTargets t,int p){int w=t.getCurrentWidth(),h=t.getCurrentHeight();var depth=binding(p,"depthtex1");var material=binding(p,"colortex1");var normal=binding(p,"colortex15");if(!base(depth,w,h)||!base(material,w,h)||!base(normal,w,h)||depth.texture()!=t.getDepthTextureNoTranslucents().getTextureId()||!owned(t,1,material.texture())||!owned(t,15,normal.texture()))return null;var domain=domain(p);return domain==null?null:new Inputs(depth,material,normal,domain);}
 private static int output(int attachment){return GL30.glGetFramebufferAttachmentParameteri(GL30.GL_DRAW_FRAMEBUFFER,attachment,GL30.GL_FRAMEBUFFER_ATTACHMENT_OBJECT_NAME);}
 private static boolean attachment(int attachment){return GL30.glGetFramebufferAttachmentParameteri(GL30.GL_DRAW_FRAMEBUFFER,attachment,GL30.GL_FRAMEBUFFER_ATTACHMENT_OBJECT_TYPE)==GL11.GL_TEXTURE&&GL30.glGetFramebufferAttachmentParameteri(GL30.GL_DRAW_FRAMEBUFFER,attachment,GL30.GL_FRAMEBUFFER_ATTACHMENT_TEXTURE_LEVEL)==0;}
 public static Draw producer(RenderTargets t,int p){int w=t.getCurrentWidth(),h=t.getCurrentHeight(),texture=output(GL30.GL_COLOR_ATTACHMENT0),fbo=GL11.glGetInteger(GL30.GL_DRAW_FRAMEBUFFER_BINDING);var rt=t.get(12);var in=inputs(t,p);boolean valid=rt!=null&&rt.getInternalFormat().name().equals("RGBA32F")&&rt.getWidth()==w&&rt.getHeight()==h&&owned(t,12,texture)&&attachment(GL30.GL_COLOR_ATTACHMENT0)&&GL11.glGetInteger(GL20.GL_DRAW_BUFFER0)==GL30.GL_COLOR_ATTACHMENT0&&GL11.glGetInteger(GL20.GL_DRAW_BUFFER1)==GL11.GL_NONE&&in!=null&&state(p,w,h,true);return new Draw(new MakeUpAoEpoch.Output(texture,fbo,w,h),in,valid);}
 public static boolean consumer(RenderTargets t,int p,int produced,Inputs expected){int w=t.getCurrentWidth(),h=t.getCurrentHeight();var field=binding(p,"colortex12");if(!base(field,w,h)||field.texture()!=produced||field.format()!=GL30.GL_RGBA32F||!Objects.equals(expected,inputs(t,p))||!state(p,w,h,false))return false;int[] indexes={3,14,12};for(int i=0;i<3;i++)if(!attachment(GL30.GL_COLOR_ATTACHMENT0+i)||!owned(t,indexes[i],output(GL30.GL_COLOR_ATTACHMENT0+i))||GL11.glGetInteger(GL20.GL_DRAW_BUFFER0+i)!=GL30.GL_COLOR_ATTACHMENT0+i)return false;return output(GL30.GL_COLOR_ATTACHMENT2)!=produced;}
 public static void upload(int p,boolean ready,int w,int h){int loc=GL20.glGetUniformLocation(p,"shaderlodBlissAoTargetReady");if(loc>=0)GL20.glUniform1i(loc,ready?1:0);loc=GL20.glGetUniformLocation(p,"shaderlodBlissAoTargetSize");if(loc>=0)GL20.glUniform2f(loc,ready?w:0,ready?h:0);}
}
